UPDATE oc_order
SET order_status = #{toStatus}
WHERE del_flag = '0'
  AND tenant_id = #{tenantId}
  AND order_no = #{orderNo}
  AND order_status = #{fromStatus}
  AND pay_status = #{fromPayStatus}

UPDATE oc_order
SET order_status = #{toStatus},
    pay_status = #{payStatus},
    pay_time = #{payTime},
    pay_trade_no = #{payTradeNo}
WHERE del_flag = '0'
  AND tenant_id = #{tenantId}
  AND order_no = #{orderNo}
  AND order_status = #{fromStatus}
  AND pay_status = #{fromPayStatus}

UPDATE oc_order
SET order_status = #{toStatus},
    shipping_time = #{shippingTime}
WHERE del_flag = '0'
  AND tenant_id = #{tenantId}
  AND order_no = #{orderNo}
  AND order_status = #{fromStatus}

UPDATE oc_order
SET order_status = #{toStatus},
    receive_time = #{receiveTime}
WHERE del_flag = '0'
  AND tenant_id = #{tenantId}
  AND order_no = #{orderNo}
  AND order_status = #{fromStatus}
